function money(minor:string, signed=false) {
  const value = BigInt(minor || '0'); const absolute = value < 0n ? -value : value;
  const whole=absolute/100n;const fraction=(absolute%100n).toString().padStart(2,'0');const formatted=`₹${new Intl.NumberFormat('en-IN').format(whole)}${fraction==='00'?'':`.${fraction}`}`;
  // A minus sign is never decoration: without this, a negative balance reads as
  // a healthy positive one. `signed` only adds the + on credits.
  if (value < 0n) return `−${formatted}`;
  return signed && value > 0n ? `+${formatted}` : formatted;
}
function ratio(part:string,total:string) { const denominator=BigInt(total||'0'); if(denominator===0n)return 0; return Number((BigInt(part||'0')*1000n)/denominator)/10; }
function rupeesToMinor(input:string) { const clean=input.replace(/,/g,'').trim(); if(!/^\d{1,12}(\.\d{1,2})?$/.test(clean))throw new Error('Enter a valid amount'); const [whole,fraction='']=clean.split('.'); return (BigInt(whole)*100n+BigInt((fraction+'00').slice(0,2))).toString(); }
function dateAt(day:string,timezone='Asia/Kolkata') {
  if(!day)return new Date().toISOString();
  const noon=new Date(`${day}T12:00:00Z`);
  const offset=(new Intl.DateTimeFormat('en-US',{timeZone:timezone,timeZoneName:'longOffset'}).formatToParts(noon).find(part=>part.type==='timeZoneName')?.value??'GMT').replace('GMT','')||'+00:00';
  return new Date(`${day}T00:00:00.000${offset}`).toISOString();
}
function rupeesOf(minor:string) { const value=BigInt(minor||'0'); const absolute=value<0n?-value:value; return `${absolute/100n}.${(absolute%100n).toString().padStart(2,'0')}`; }
function apiBase() { if(configuredApiUrl)return configuredApiUrl; if(typeof window!=='undefined'&&['localhost','127.0.0.1'].includes(window.location.hostname))return 'http://localhost:4000'; return ''; }
function invitationToken() { if(typeof window==='undefined')return null; const fragmentQuery=window.location.hash.split('?')[1]??''; return new URLSearchParams(fragmentQuery).get('invite')??new URLSearchParams(window.location.search).get('invite'); }
class ApiError extends Error { unreachable:boolean; constructor(message:string,unreachable=false){super(message);this.unreachable=unreachable;} }
async function api<T>(path:string,options:RequestInit={}):Promise<T> {
  const base=apiBase(); if(!base)throw new ApiError('The dashboard is not configured with an API address',true);
  const authHeaders=await apiAuthHeaders();
  let response:Response;
  try{ response=await fetch(`${base}${path}`,{...options,signal:options.signal??AbortSignal.timeout(12000),headers:{...(options.body?{'content-type':'application/json'}:{}),...authHeaders,...options.headers}}); }
  catch(error){ throw new ApiError(error instanceof DOMException&&error.name==='TimeoutError'?`${base} did not respond in time`:`Cannot reach the ledger at ${base}`,true); }
  if(!response.ok){let message='Request failed';try{message=((await response.json()) as {message?:string}).message??message;}catch{}throw new ApiError(response.status===429?'Too many requests in a short time. Wait a moment and try again.':message);}
  if(response.status===204)return undefined as T;
  return response.json() as Promise<T>;
}
type Listed<T> = { items:T[] };
function initials(name:string|null|undefined,email='') { return (name||email||'?').split(/\s|@/).filter(Boolean).slice(0,2).map(part=>part[0]).join('').toUpperCase(); }
function readableAction(action:string){return ({'transaction.reclassified':'Reclassified a transaction','transaction.created':'Added a transaction','transaction.split':'Split a transaction','transaction.commented':'Added a review comment','period.verified':'Verified the monthly books','period.in_review':'Started monthly review','budget.updated':'Updated a budget','membership.role_changed':'Changed member access'} as Record<string,string>)[action]??action.replaceAll('.',' · ').replaceAll('_',' ');}
function currentPeriod(timezone='Asia/Kolkata'){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:timezone,year:'numeric',month:'2-digit'}).formatToParts(new Date());const year=parts.find(part=>part.type==='year')?.value??'2026';const month=parts.find(part=>part.type==='month')?.value??'08';const value=`${year}-${month}`;return{value,label:new Date(`${value}-01T00:00:00Z`).toLocaleDateString('en-IN',{month:'long',year:'numeric',timeZone:'UTC'})};}
function fileSize(bytes:number){if(bytes<1024)return `${bytes} B`;if(bytes<1024*1024)return `${(bytes/1024).toFixed(0)} KB`;return `${(bytes/(1024*1024)).toFixed(1)} MB`;}
function statementType(file:File){const name=file.name.toLowerCase();if(file.type==='text/csv'||name.endsWith('.csv'))return 'text/csv';if(file.type==='application/pdf'||name.endsWith('.pdf'))return 'application/pdf';throw new Error('Only CSV or PDF bank statements can be imported');}
async function sha256Hex(file:File){const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());return Array.from(new Uint8Array(digest)).map(byte=>byte.toString(16).padStart(2,'0')).join('');}
function monthKey(value:string,timezone:string){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:timezone,year:'numeric',month:'2-digit'}).formatToParts(new Date(value));return `${parts.find(part=>part.type==='year')?.value}-${parts.find(part=>part.type==='month')?.value}`;}

export default function Home(){
  const [view,setView]=useState<View>('overview'); const [books,setBooks]=useState<Book[]>(demoEnabled?demoBooks:[]); const [bookId,setBookId]=useState(demoEnabled?'book_arjun':'');
  const [summary,setSummary]=useState<Summary>(demoEnabled?demoSummary:emptySummary); const [transactions,setTransactions]=useState<Transaction[]>(demoEnabled?demoTransactions:[]); const [categories,setCategories]=useState<Category[]>(demoEnabled?demoCategories:[]);
  const [budgets,setBudgets]=useState<Budget[]>(demoEnabled?demoBudgets:[]); const [members,setMembers]=useState<Member[]>(demoEnabled?demoMembers:[]); const [recurring,setRecurring]=useState<Recurring[]>(demoEnabled?demoRecurring:[]); const [audit,setAudit]=useState<AuditEvent[]>(demoEnabled?demoAudit:[]);
  const [invitations,setInvitations]=useState<Invitation[]>([]); const [actorUserId,setActorUserId]=useState(demoEnabled?'user_owner':'');
  const [accounts,setAccounts]=useState<AccountRecord[]>(demoEnabled?demoAccounts:[]); const [rules,setRules]=useState<Rule[]>(demoEnabled?demoRules:[]); const [imports,setImports]=useState<ImportRecord[]>(demoEnabled?demoImports:[]);
  const [dialog,setDialog]=useState<Dialog>(null); const [editing,setEditing]=useState<AccountRecord|Category|Rule|Recurring|null>(null); const [inviteLink,setInviteLink]=useState<{email:string;url:string}|null>(null); const [selected,setSelected]=useState<Transaction|null>(null); const [toast,setToast]=useState(''); const [saving,setSaving]=useState(false);
  const [userLabel,setUserLabel]=useState('Arjun Mohanesh'); const [actorEmail,setActorEmail]=useState('');
  const [actorKey,setActorKey]=useState(firebaseEnabled?'':'dev-owner'); const actorRef=useRef(firebaseEnabled?'':'dev-owner'); const requestGeneration=useRef(0); const [loadedContext,setLoadedContext]=useState<LoadedContext|null>(demoEnabled?{actorKey:'dev-owner',bookId:'book_arjun'}:null);
  const [authState,setAuthState]=useState<'loading'|'signed-in'|'signed-out'>(firebaseEnabled?'loading':'signed-in'); const [dataMode,setDataMode]=useState<'checking'|'live'|'demo'|'error'>(demoEnabled?'demo':'checking'); const [loadError,setLoadError]=useState('');
  const [search,setSearch]=useState(''); const [stateFilter,setStateFilter]=useState('all'); const [kindFilter,setKindFilter]=useState('all'); const [notificationsOpen,setNotificationsOpen]=useState(false); const [accountOpen,setAccountOpen]=useState(false);
  const activeBook=books.find(book=>book.id===bookId)??books[0]; const categoryMap=useMemo(()=>Object.fromEntries(categories.map(category=>[category.id,category.name])),[categories]);
  const pending=transactions.find(transaction=>transaction.state==='pending_review'); const canManage=['workspace_admin','book_owner'].includes(activeBook?.role??''); const canEdit=['workspace_admin','book_owner','editor'].includes(activeBook?.role??''); const canReview=['workspace_admin','book_owner','editor','reviewer'].includes(activeBook?.role??''); const actionsEnabled=dataMode==='live'||dataMode==='demo';
  const filteredTransactions=useMemo(()=>transactions.filter(tx=>(!search||`${tx.merchant??''} ${categoryMap[tx.categoryId??'']??''}`.toLowerCase().includes(search.toLowerCase()))&&(stateFilter==='all'||tx.state===stateFilter)&&(kindFilter==='all'||tx.kind===kindFilter)),[transactions,search,stateFilter,kindFilter,categoryMap]);
  const period=dataMode==='demo'?{value:'2026-08',label:'August 2026'}:currentPeriod(activeBook?.timezone);
  const flash=useCallback((message:string)=>{setToast(message);window.setTimeout(()=>setToast(''),3200);},[]);
  const reportFailure=useCallback((error:unknown,fallback:string)=>{const message=error instanceof Error?error.message:fallback;if(error instanceof ApiError&&error.unreachable){requestGeneration.current+=1;setLoadError(message);setLoadedContext(null);setDataMode('error');setDialog(null);setSelected(null);}flash(message);},[flash]);
  function navigate(next:View){setView(next);window.history.replaceState(null,'',`#${next}`);setSearch('');}
  const clearSensitiveState=useCallback(()=>{setBooks([]);setBookId('');setSummary(emptySummary);setTransactions([]);setCategories([]);setBudgets([]);setMembers([]);setRecurring([]);setAudit([]);setInvitations([]);setActorUserId('');setActorEmail('');setAccounts([]);setRules([]);setImports([]);setSelected(null);setDialog(null);setLoadedContext(null);},[]);

  useEffect(()=>{if(!firebaseEnabled)return;return observeUser(user=>{requestGeneration.current+=1;if(!user){actorRef.current='';setActorKey('');clearSensitiveState();setAuthState('signed-out');return;}if(actorRef.current&&actorRef.current!==user.uid)clearSensitiveState();actorRef.current=user.uid;setActorKey(user.uid);setUserLabel(user.displayName??user.email?.split('@')[0]??'Paisa user');setAuthState('signed-in');});},[clearSensitiveState]);
  useEffect(()=>{const hash=window.location.hash.slice(1).split('?')[0] as View;if(navItems.some(item=>item.id===hash))queueMicrotask(()=>setView(hash));const onHash=()=>{const next=window.location.hash.slice(1).split('?')[0] as View;if(navItems.some(item=>item.id===next))setView(next);};window.addEventListener('hashchange',onHash);return()=>window.removeEventListener('hashchange',onHash);},[]);
  useEffect(()=>{const close=(event:KeyboardEvent)=>{if(event.key==='Escape'){setDialog(null);setNotificationsOpen(false);}};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close);},[]);

  const refresh=useCallback(async(selectedBook:string)=>{const generation=++requestGeneration.current;const requestedActor=actorRef.current;if(demoEnabled){setLoadedContext({actorKey:requestedActor,bookId:selectedBook||'book_arjun'});setDataMode('demo');return;}setLoadedContext(null);setDataMode('checking');setLoadError('');try{const [me,bookData]=await Promise.all([api<{id:string;displayName:string|null;email:string}>('/v1/me'),api<Listed<Book>>('/v1/books')]);const availableBooks:Book[]=bookData.items;if(!availableBooks.length)throw new Error('No financial books are assigned to this account');const preferredBook=availableBooks.find(book=>book.visibility==='private'&&book.role==='book_owner')??availableBooks.find(book=>book.visibility==='private')??availableBooks[0];const resolvedBook=availableBooks.some(book=>book.id===selectedBook)?selectedBook:preferredBook.id;const targetBook=availableBooks.find(book=>book.id===resolvedBook)!;const resolvedPeriod=currentPeriod(targetBook.timezone).value;const targetCanManage=['workspace_admin','book_owner'].includes(targetBook.role);const [summaryData,transactionData,categoryData,budgetResult,recurringResult,auditResult,accountResult,ruleResult,importResult,memberResult,invitationResult]=await Promise.all([
      api<Summary>(`/v1/books/${resolvedBook}/summary?month=${resolvedPeriod}`),api<Listed<Transaction>>(`/v1/books/${resolvedBook}/transactions?limit=100`),api<Listed<Category>>(`/v1/books/${resolvedBook}/categories`),
      api<Listed<Budget>>(`/v1/books/${resolvedBook}/budgets`),api<Listed<Recurring>>(`/v1/books/${resolvedBook}/recurring-plans`),api<Listed<AuditEvent>>(`/v1/books/${resolvedBook}/audit-events`),
      api<Listed<AccountRecord>>(`/v1/books/${resolvedBook}/accounts`),api<Listed<Rule>>(`/v1/books/${resolvedBook}/categorization-rules`),api<Listed<ImportRecord>>(`/v1/books/${resolvedBook}/imports`),
      targetCanManage?api<Listed<Member>>(`/v1/books/${resolvedBook}/memberships`):Promise.resolve({items:[]}),targetCanManage?api<Listed<Invitation>>(`/v1/books/${resolvedBook}/invitations`):Promise.resolve({items:[]}),
    ]);if(generation!==requestGeneration.current||requestedActor!==actorRef.current)return;setActorUserId(me.id);setActorEmail(me.email);if(me.displayName)setUserLabel(me.displayName);setBooks(availableBooks);setBookId(resolvedBook);setSummary(summaryData);setTransactions(transactionData.items);setSelected(current=>current?transactionData.items.find(item=>item.id===current.id)??null:null);setCategories(categoryData.items);setBudgets(budgetResult.items.filter((budget:Budget)=>String(budget.month).slice(0,7)===resolvedPeriod));setRecurring(recurringResult.items);setAudit(auditResult.items);setAccounts(accountResult.items);setRules(ruleResult.items);setImports(importResult.items);setMembers(memberResult.items);setInvitations(invitationResult.items);setLoadedContext({actorKey:requestedActor,bookId:resolvedBook});setDataMode('live');
    }catch(error){if(generation!==requestGeneration.current||requestedActor!==actorRef.current)return;setLoadError(error instanceof Error?error.message:'The ledger is temporarily unavailable');setLoadedContext(null);setDataMode('error');}},[]);
  useEffect(()=>{if(authState!=='signed-in')return;const timer=window.setTimeout(()=>void refresh(bookId),0);return()=>window.clearTimeout(timer);},[bookId,authState,refresh]);
  useEffect(()=>{if(authState!=='signed-in')return;const token=invitationToken();if(!token)return;void api<{bookId:string;role:string}>('/v1/invitations/accept',{method:'POST',body:JSON.stringify({token})}).then(async result=>{window.history.replaceState(null,'',`/#people`);setBookId(result.bookId);setView('people');await refresh(result.bookId);flash('Invitation accepted — the shared book is ready');}).catch(error=>reportFailure(error,'Could not accept invitation'));},[authState,refresh,flash,reportFailure]);

  function switchBook(nextBookId:string){requestGeneration.current+=1;setLoadedContext(null);setDataMode('checking');setBookId(nextBookId);}
  async function addTransaction(event:FormEvent<HTMLFormElement>){event.preventDefault();setSaving(true);const form=new FormData(event.currentTarget);const kind=String(form.get('kind'));try{let minor=rupeesToMinor(String(form.get('amount')));if(kind==='expense')minor=(-BigInt(minor)).toString();const draft:Transaction={id:crypto.randomUUID(),merchant:String(form.get('merchant')),kind,state:'confirmed',amountMinor:minor,categoryId:String(form.get('categoryId')),occurredAt:dateAt(String(form.get('occurredAt')),activeBook?.timezone),meta:'Manual entry'};if(dataMode==='live'){await api<Transaction>(`/v1/books/${bookId}/transactions`,{method:'POST',headers:{'idempotency-key':crypto.randomUUID()},body:JSON.stringify(draft)});await refresh(bookId);}else if(dataMode==='demo')setTransactions(items=>[draft,...items]);else throw new Error('Reconnect to the live ledger before saving');setDialog(null);flash('Transaction added to this book');}catch(error){reportFailure(error,'Could not add transaction');}finally{setSaving(false);}}
  async function setCategory(transaction:Transaction,categoryId:string,applyToFuture=false){setSaving(true);try{if(dataMode==='live'){await api<Transaction>(`/v1/books/${bookId}/transactions/${transaction.id}/category`,{method:'PATCH',body:JSON.stringify({categoryId,applyToFuture})});await refresh(bookId);}else if(dataMode==='demo')setTransactions(items=>items.map(item=>item.id===transaction.id?{...item,categoryId,state:'confirmed'}:item));else throw new Error('Reconnect to the live ledger before saving');setDialog(null);setSelected(null);flash(applyToFuture?'Category saved and future rule created':'Category saved and audit trail updated');}catch(error){reportFailure(error,'Could not update category');}finally{setSaving(false);}}
  async function correctTransaction(transaction:Transaction,fields:Record<string,string>){setSaving(true);try{if(dataMode==='live'){const updated=await api<Transaction>(`/v1/books/${bookId}/transactions/${transaction.id}`,{method:'PATCH',body:JSON.stringify(fields)});patchTransaction(transaction.id,updated);await refresh(bookId);}else if(dataMode==='demo')patchTransaction(transaction.id,fields as Partial<Transaction>);else throw new Error('Reconnect to the live ledger before saving');setDialog(null);setSelected(null);flash('Entry corrected — the previous values are in the audit trail');}catch(error){reportFailure(error,'Could not correct this entry');}finally{setSaving(false);}}
  async function voidTransaction(transaction:Transaction){setSaving(true);try{if(dataMode==='live'){await api<Transaction>(`/v1/books/${bookId}/transactions/${transaction.id}`,{method:'PATCH',body:JSON.stringify({state:'voided'})});await refresh(bookId);}else if(dataMode==='demo')patchTransaction(transaction.id,{state:'voided'});else throw new Error('Reconnect to the live ledger before saving');setDialog(null);setSelected(null);flash('Entry voided — it stays in the ledger but no longer counts');}catch(error){reportFailure(error,'Could not void this entry');}finally{setSaving(false);}}
  async function saveBudget(event:FormEvent<HTMLFormElement>){event.preventDefault();setSaving(true);const form=new FormData(event.currentTarget);try{const categoryId=String(form.get('categoryId'));const amountMinor=rupeesToMinor(String(form.get('amount')));const month=String(form.get('month'))+'-01';if(dataMode==='live'){await api<Budget>(`/v1/books/${bookId}/budgets/${categoryId}`,{method:'PUT',body:JSON.stringify({month,amountMinor,currency:'INR'})});await refresh(bookId);}else if(dataMode==='demo')setBudgets(items=>{const exists=items.find(item=>item.categoryId===categoryId&&item.month.slice(0,7)===month.slice(0,7));return exists?items.map(item=>item.id===exists.id?{...item,amountMinor}:item):[...items,{id:crypto.randomUUID(),categoryId,amountMinor,month}];});else throw new Error('Reconnect to the live ledger before saving');setDialog(null);flash('Monthly budget saved');}catch(error){reportFailure(error,'Could not save budget');}finally{setSaving(false);}}
  async function updateRole(member:Member,role:string){if(!actionsEnabled){flash('Reconnect to the live ledger before changing access');return;}const previous=member.role;setMembers(items=>items.map(item=>item.userId===member.userId?{...item,role}:item));try{if(dataMode==='live')await api<Member>(`/v1/books/${bookId}/memberships/${member.userId}`,{method:'PATCH',body:JSON.stringify({role})});flash(`${member.user.displayName??member.user.email} is now ${roleLabels[role]??role.replace('_',' ')}`);}catch(error){setMembers(items=>items.map(item=>item.userId===member.userId?{...item,role:previous}:item));reportFailure(error,'Could not change access');}}
  async function removeMember(member:Member){if(!actionsEnabled){flash('Reconnect to the live ledger before changing access');return;}setSaving(true);try{if(dataMode==='live')await api<void>(`/v1/books/${bookId}/memberships/${member.userId}`,{method:'DELETE'});setMembers(items=>items.filter(item=>item.userId!==member.userId));flash(`${member.user.displayName??member.user.email} no longer has access to this book`);}catch(error){reportFailure(error,'Could not remove this person');}finally{setSaving(false);}}
  async function revokeInvitation(invitation:Invitation){if(!actionsEnabled){flash('Reconnect to the live ledger before changing access');return;}setSaving(true);try{if(dataMode==='live')await api<void>(`/v1/books/${bookId}/invitations/${invitation.id}`,{method:'DELETE'});setInvitations(items=>items.filter(item=>item.id!==invitation.id));flash(`Invitation to ${invitation.email} revoked`);}catch(error){reportFailure(error,'Could not revoke this invitation');}finally{setSaving(false);}}
  async function saveProfile(event:FormEvent<HTMLFormElement>){event.preventDefault();setSaving(true);const displayName=String(new FormData(event.currentTarget).get("displayName")).trim();try{if(dataMode==='live')await api<{displayName:string|null}>('/v1/me',{method:'PATCH',body:JSON.stringify({displayName})});else if(dataMode!=='demo')throw new Error('Reconnect to the live ledger before saving');setUserLabel(displayName);closeDialog();flash('Profile updated');}catch(error){reportFailure(error,'Could not update your profile');}finally{setSaving(false);}}
  async function inviteMember(event:FormEvent<HTMLFormElement>){event.preventDefault();setSaving(true);const form=new FormData(event.currentTarget);const email=String(form.get('email')).trim().toLowerCase();const role=String(form.get('role'));try{if(dataMode==='live'){const invitation=await api<Invitation&{token:string}>(`/v1/books/${bookId}/invitations`,{method:'POST',body:JSON.stringify({email,role})});setInvitations(items=>[invitation,...items.filter(item=>item.email!==email)]);setInviteLink({email,url:`${window.location.origin}/#people?invite=${encodeURIComponent(invitation.token)}`});setDialog('invite-link');}else if(dataMode==='demo'){setInvitations(items=>[{id:crypto.randomUUID(),email,role,status:'pending',createdAt:new Date().toISOString(),expiresAt:new Date(Date.now()+7*86400000).toISOString()},...items]);setInviteLink({email,url:`${window.location.origin}/#people?invite=sample-token-not-valid`});setDialog('invite-link');}else throw new Error('Reconnect to the live ledger before creating an invitation');}catch(error){reportFailure(error,'Could not create the invitation');}finally{setSaving(false);}}
  async function verifyPeriod(){try{if(dataMode==='live')await api<unknown>(`/v1/books/${bookId}/period-reviews`,{method:'POST',body:JSON.stringify({month:period.value,status:'verified',note:'Verified from the dashboard'})});else if(dataMode!=='demo')throw new Error('Reconnect to the live ledger before verifying');setAudit(items=>[{id:crypto.randomUUID(),action:'period.verified',actorId:'user_owner',createdAt:new Date().toISOString()},...items]);flash(`${period.label} books marked as verified`);}catch(error){reportFailure(error,'Could not verify period');}}
  function patchTransaction(id:string,change:Partial<Transaction>){setTransactions(items=>items.map(item=>item.id===id?{...item,...change}:item));setSelected(item=>item&&item.id===id?{...item,...change}:item);}
  async function saveSplit(transaction:Transaction,parts:{categoryId:string;amount:string}[]){setSaving(true);try{const negative=BigInt(transaction.amountMinor)<0n;const splits=parts.map(part=>{const minor=rupeesToMinor(part.amount);return{categoryId:part.categoryId,amountMinor:negative?`-${minor}`:minor};});const total=splits.reduce((sum,split)=>sum+(BigInt(split.amountMinor)<0n?-BigInt(split.amountMinor):BigInt(split.amountMinor)),0n);const expected=negative?-BigInt(transaction.amountMinor):BigInt(transaction.amountMinor);if(total!==expected)throw new Error(`Split parts must add up to ${money(transaction.amountMinor)}`);
    if(dataMode==='live'){const updated=await api<Transaction>(`/v1/books/${bookId}/transactions/${transaction.id}/splits`,{method:'PUT',body:JSON.stringify({splits})});patchTransaction(transaction.id,{splits:updated.splits});await refresh(bookId);}else if(dataMode==='demo')patchTransaction(transaction.id,{splits:splits.map((split,index)=>({id:`split_${index}_${crypto.randomUUID()}`,...split}))});else throw new Error('Reconnect to the live ledger before saving');
    setDialog('transaction');flash('Split saved without changing the imported amount');}catch(error){reportFailure(error,'Could not split this transaction');}finally{setSaving(false);}}
  async function postComment(transaction:Transaction,body:string){setSaving(true);try{let comment:CommentEntry;if(dataMode==='live')comment=await api<CommentEntry>(`/v1/books/${bookId}/transactions/${transaction.id}/comments`,{method:'POST',body:JSON.stringify({body})});else if(dataMode==='demo')comment={id:crypto.randomUUID(),body,authorId:'user_owner',createdAt:new Date().toISOString()};else throw new Error('Reconnect to the live ledger before commenting');
    patchTransaction(transaction.id,{comments:[...(transaction.comments??[]),comment]});flash('Comment added to the review thread');}catch(error){reportFailure(error,'Could not add the comment');}finally{setSaving(false);}}
  function closeDialog(){setDialog(null);setEditing(null);setInviteLink(null);}
  function openEditor(next:Dialog,record:AccountRecord|Category|Rule|Recurring|null=null){setEditing(record);setDialog(next);}
  async function removeSetting(){setSaving(true);try{if(dataMode!=='live'&&dataMode!=='demo')throw new Error('Reconnect to the live ledger before removing');const live=dataMode==='live';if(dialog==='account'){const target=editing as AccountRecord;if(live)await api<AccountRecord>(`/v1/books/${bookId}/accounts/${target.id}`,{method:'PATCH',body:JSON.stringify({archived:true})});setAccounts(items=>items.filter(item=>item.id!==target.id));flash(`${target.name} archived — its transactions are untouched`);}else if(dialog==='category'){const target=editing as Category;if(live)await api<Category>(`/v1/books/${bookId}/categories/${target.id}`,{method:'PATCH',body:JSON.stringify({archived:true})});setCategories(items=>items.filter(item=>item.id!==target.id));flash(`${target.name} archived — past entries keep it`);}else if(dialog==='rule'){const target=editing as Rule;if(live)await api<void>(`/v1/books/${bookId}/categorization-rules/${target.id}`,{method:'DELETE'});setRules(items=>items.filter(item=>item.id!==target.id));flash('Rule removed');}else if(dialog==='recurring'){const target=editing as Recurring;if(live)await api<Recurring>(`/v1/books/${bookId}/recurring-plans/${target.id}`,{method:'PATCH',body:JSON.stringify({active:false})});setRecurring(items=>items.filter(item=>item.id!==target.id));flash(`${target.name} stopped`);}closeDialog();}catch(error){reportFailure(error,'Could not remove this item');}finally{setSaving(false);}}
  async function saveAccount(event:FormEvent<HTMLFormElement>){event.preventDefault();setSaving(true);const form=new FormData(event.currentTarget);const draft={name:String(form.get('name')).trim(),institution:String(form.get('institution')).trim()||null,accountMask:String(form.get('accountMask')).trim()||null,accountType:String(form.get('accountType')),currency:'INR'};const target=editing as AccountRecord|null;try{const account=dataMode==='live'?await api<AccountRecord>(target?`/v1/books/${bookId}/accounts/${target.id}`:`/v1/books/${bookId}/accounts`,{method:target?'PATCH':'POST',body:JSON.stringify(draft)}):dataMode==='demo'?{id:target?.id??crypto.randomUUID(),...draft}:null;if(!account)throw new Error('Reconnect to the live ledger before saving');setAccounts(items=>target?items.map(item=>item.id===target.id?account:item):[...items,account]);closeDialog();flash(target?`${draft.name} updated`:`${draft.name} is now tracked in this book`);}catch(error){reportFailure(error,'Could not save the account');}finally{setSaving(false);}}
  async function saveCategory(event:FormEvent<HTMLFormElement>){event.preventDefault();setSaving(true);const form=new FormData(event.currentTarget);const draft={name:String(form.get('name')).trim(),groupName:String(form.get('groupName')),color:String(form.get('color'))};const target=editing as Category|null;try{const category=dataMode==='live'?await api<Category>(target?`/v1/books/${bookId}/categories/${target.id}`:`/v1/books/${bookId}/categories`,{method:target?'PATCH':'POST',body:JSON.stringify(draft)}):dataMode==='demo'?{id:target?.id??crypto.randomUUID(),...draft}:null;if(!category)throw new Error('Reconnect to the live ledger before saving');setCategories(items=>target?items.map(item=>item.id===target.id?category:item):[...items,category]);closeDialog();flash(target?`${draft.name} updated`:`${draft.name} is ready to use`);}catch(error){reportFailure(error,'Could not save the category');}finally{setSaving(false);}}
  async function saveRule(event:FormEvent<HTMLFormElement>){event.preventDefault();setSaving(true);const form=new FormData(event.currentTarget);const draft={categoryId:String(form.get('categoryId')),matchType:String(form.get('matchType')),matchValue:String(form.get('matchValue')).trim(),priority:Number(form.get('priority'))};const target=editing as Rule|null;try{const rule=dataMode==='live'?await api<Rule>(target?`/v1/books/${bookId}/categorization-rules/${target.id}`:`/v1/books/${bookId}/categorization-rules`,{method:target?'PATCH':'POST',body:JSON.stringify(draft)}):dataMode==='demo'?{id:target?.id??crypto.randomUUID(),...draft}:null;if(!rule)throw new Error('Reconnect to the live ledger before saving');setRules(items=>(target?items.map(item=>item.id===target.id?rule:item):[...items,rule]).sort((a,b)=>a.priority-b.priority));closeDialog();flash(target?'Rule updated for future payments':'Rule saved for future payments only');}catch(error){reportFailure(error,'Could not save the rule');}finally{setSaving(false);}}
  async function saveRecurring(event:FormEvent<HTMLFormElement>){event.preventDefault();setSaving(true);const form=new FormData(event.currentTarget);const kind=String(form.get('kind'));const target=editing as Recurring|null;try{let amountMinor=rupeesToMinor(String(form.get('amount')));if(kind==='expense')amountMinor=`-${amountMinor}`;const draft={name:String(form.get('name')).trim(),kind,amountMinor,categoryId:String(form.get('categoryId')),cadence:String(form.get('cadence')),nextDueAt:new Date(`${String(form.get('nextDueAt'))}T00:00:00.000Z`).toISOString(),currency:'INR'};const plan=dataMode==='live'?await api<Recurring>(target?`/v1/books/${bookId}/recurring-plans/${target.id}`:`/v1/books/${bookId}/recurring-plans`,{method:target?'PATCH':'POST',body:JSON.stringify(draft)}):dataMode==='demo'?{id:target?.id??crypto.randomUUID(),...draft}:null;if(!plan)throw new Error('Reconnect to the live ledger before saving');setRecurring(items=>(target?items.map(item=>item.id===target.id?plan:item):[...items,plan]).sort((a,b)=>a.nextDueAt.localeCompare(b.nextDueAt)));closeDialog();flash(target?`${draft.name} updated`:`${draft.name} added to upcoming payments`);}catch(error){reportFailure(error,'Could not save the recurring plan');}finally{setSaving(false);}}
  async function importStatement(file:File,accountId:string){setSaving(true);try{const contentType=statementType(file);if(file.size>(contentType==='text/csv'?2*1024*1024:10*1024*1024))throw new Error(contentType==='text/csv'?'CSV statements must be 2 MB or smaller':'Statements must be 10 MB or smaller');const sha256=await sha256Hex(file);const draft={fileName:file.name,contentType,sizeBytes:file.size,sha256};
    // CSV rows are parsed and posted to the ledger server-side; PDFs are only fingerprinted for now.
    const content=contentType==='text/csv'?await file.text():undefined;
    const record=dataMode==='live'?await api<ImportResult>(`/v1/books/${bookId}/imports`,{method:'POST',body:JSON.stringify({...draft,...(content?{content,accountId:accountId||null}:{})})}):dataMode==='demo'?{id:crypto.randomUUID(),...draft,status:'upload_pending',createdAt:new Date().toISOString(),duplicate:imports.some(item=>item.sha256===sha256)}:null;if(!record)throw new Error('Reconnect to the live ledger before importing');
    if(!record.duplicate)setImports(items=>[record,...items]);
    // Rows are deduplicated individually, so a re-uploaded file still reports what it actually added.
    flash(record.imported===undefined?record.duplicate?'This statement was already imported — no duplicate entries were created':'Statement queued for parsing and reconciliation':record.imported?`${record.imported} entr${record.imported===1?'y':'ies'} imported${record.duplicates?`, ${record.duplicates} already in the ledger`:''}${record.warnings?.length?` · ${record.warnings.length} warning${record.warnings.length===1?'':'s'}`:''}`:'Every entry in this statement is already in the ledger');
    if(record.warnings?.length)console.warn('Statement import warnings',record.warnings);
    setDialog(null);if(dataMode==='live'&&record.imported)await refresh(bookId);}catch(error){reportFailure(error,'Could not import this statement');}finally{setSaving(false);}}
  function downloadCsv(){const rows=[['Date','Merchant','Type','Category','State','Amount (paise)'],...filteredTransactions.map(tx=>[tx.occurredAt,tx.merchant??'',tx.kind,categoryMap[tx.categoryId??'']??'Uncategorized',tx.state,tx.amountMinor])];const csv=rows.map(row=>row.map(cell=>`"${String(cell).replaceAll('"','""')}"`).join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const link=document.createElement('a');link.href=url;link.download=`paisa-${bookId}-${period.value}.csv`;link.click();URL.revokeObjectURL(url);flash('Visible ledger rows downloaded as CSV');}

  const stats=[{label:'Income',value:money(summary.incomeMinor),detail:'Received this month',tone:'mint',icon:'↓'},{label:'Spent',value:money(summary.spentMinor),detail:BigInt(summary.incomeMinor||'0')>0n?`${ratio(summary.spentMinor,summary.incomeMinor).toFixed(1)}% of income`:'No income recorded this month',tone:'coral',icon:'↑'},{label:'Saved',value:money(summary.savedMinor),detail:BigInt(summary.savedMinor||'0')<0n?'Spent more than you received':'Income minus spending — not your balance',tone:'navy',icon:'◆'}];
  const spentByCategory=(categoryId:string)=>(summary.byCategory?.find(item=>item.categoryId===categoryId)?.amountMinor??'0');
  const totalBudget=budgets.reduce((sum,budget)=>sum+BigInt(budget.amountMinor),0n).toString();const budgetUse=ratio(summary.spentMinor,totalBudget);
  const budgetAtRisk=budgets.map(budget=>({...budget,used:ratio(spentByCategory(budget.categoryId),budget.amountMinor)})).find(budget=>budget.used>=85);
  const contentReady=dataMode==='demo'||(dataMode==='live'&&loadedContext?.actorKey===actorKey&&loadedContext.bookId===bookId);

  if(authState==='loading')return <main className="auth-page"><div className="auth-card"><div className="brand auth-brand"><span className="brand-mark">₹</span><span>Paisa</span></div><div className="loading-line"/><p>Opening your private financial workspace…</p></div></main>;
  if(authState==='signed-out')return <SignIn/>;
  return <main className="app-shell">
    <aside className="sidebar"><button className="brand brand-button" onClick={()=>navigate('overview')}><span className="brand-mark">₹</span><span>Paisa</span></button><nav aria-label="Primary navigation">{navItems.map(item=><a className={`nav-item ${view===item.id?'active':''}`} href={`#${item.id}`} onClick={event=>{event.preventDefault();navigate(item.id);}} key={item.id}><span aria-hidden="true">{item.icon}</span>{item.label}{item.id==='transactions'&&summary.pendingReview>0?<b>{summary.pendingReview}</b>:null}</a>)}</nav><div className="support-card"><span>◈</span><div><strong>Private capture</strong><small>Raw SMS stays on device</small></div><i/></div><div className="sidebar-footer"><p>Your financial book</p><label className="workspace-switcher"><span className="avatar small">{initials(userLabel)}</span><span>{activeBook?.name}<small>{activeBook?.visibility} · {activeBook?.role.replace('_',' ')}</small></span><select aria-label="Select financial book" value={bookId} onChange={event=>switchBook(event.target.value)}>{books.map(book=><option value={book.id} key={book.id}>{book.name}</option>)}</select></label></div></aside>
    <section className="main-panel"><header className="topbar"><div><p className="eyebrow">{activeBook?.name??'Financial workspace'} · {period.label.toUpperCase()}</p><h1>{view==='overview'?`Good evening, ${userLabel.split(/\s|@/)[0]}`:({transactions:'Transactions',budgets:'Budgets',reports:'Reports',people:'People & access'} as Record<string,string>)[view]}</h1></div><div className="top-actions"><label className="global-search"><span>⌕</span><input aria-label="Search transactions" placeholder="Search payments" value={search} onChange={event=>{setSearch(event.target.value);if(event.target.value&&view!=='transactions')navigate('transactions');}}/></label><button className="icon-button" aria-label="Notifications" aria-expanded={notificationsOpen} onClick={()=>setNotificationsOpen(open=>!open)}>●<span className="notification-dot"/></button>{canEdit&&actionsEnabled?<button className="primary-button" onClick={()=>setDialog('add')}>+ Add transaction</button>:null}<button className="avatar avatar-button" aria-label="Account menu" aria-expanded={accountOpen} onClick={()=>{setAccountOpen(open=>!open);setNotificationsOpen(false);}}>{initials(userLabel)}</button></div></header>
      {notificationsOpen?<aside className="notification-panel"><div className="panel-title"><div><p className="eyebrow">NOTIFICATIONS</p><h2>What needs attention</h2></div><button aria-label="Close notifications" onClick={()=>setNotificationsOpen(false)}>×</button></div>{summary.pendingReview?<button onClick={()=>{navigate('transactions');setStateFilter('pending_review');setNotificationsOpen(false);}}><span className="notice-icon coral">!</span><div><strong>{summary.pendingReview} payments need review</strong><small>Confirm their categories while they are fresh.</small></div></button>:null}{budgetAtRisk?<button onClick={()=>{navigate('budgets');setNotificationsOpen(false);}}><span className="notice-icon lime">%</span><div><strong>{categoryMap[budgetAtRisk.categoryId]??'A budget'} needs attention</strong><small>{budgetAtRisk.used.toFixed(0)}% of its monthly limit is used.</small></div></button>:null}{!summary.pendingReview&&!budgetAtRisk?<p className="quiet">No alerts for this book.</p>:null}</aside>:null}
      {accountOpen?<aside className="account-panel"><div className="panel-title"><div><strong>{userLabel}</strong><small>{actorEmail||"Signed in"}</small></div><button aria-label="Close account menu" onClick={()=>setAccountOpen(false)}>×</button></div><p className="eyebrow">YOUR BOOKS</p><div className="account-books">{books.map(book=><button key={book.id} className={book.id===bookId?"active":""} onClick={()=>{setAccountOpen(false);switchBook(book.id);}}><span>{book.name}</span><small>{book.visibility} · {roleLabels[book.role]??book.role.replace("_"," ")}</small>{book.id===bookId?<em>✓</em>:null}</button>)}</div><div className="account-actions"><button className="secondary-button" onClick={()=>{setAccountOpen(false);setDialog("profile");}}>Edit profile</button><button className="text-button danger-link" onClick={()=>void signOutUser()}>Sign out</button></div></aside>:null}
      <div className="content">{dataMode!=='live'?<div className={`environment-banner ${dataMode}`}><span>{dataMode==='checking'?'↻':dataMode==='error'?'!':'◇'}</span><div><strong>{dataMode==='checking'?'Connecting to your ledger…':dataMode==='error'?'Live ledger unavailable':'Preview mode — sample data only'}</strong><small>{dataMode==='checking'?'Securely loading this book.':dataMode==='error'?`${loadError}. No changes can be saved until reconnection.`:'This build has explicit demo mode enabled. Sample changes never leave this browser.'}</small></div>{dataMode==='error'?<button className="secondary-button" onClick={()=>void refresh(bookId)}>Retry</button>:null}</div>:null}
        {contentReady&&view==='overview'?<Overview summary={summary} stats={stats} transactions={transactions} categories={categories} categoryMap={categoryMap} budgets={budgets} recurring={recurring} pending={pending} spentByCategory={spentByCategory} periodLabel={period.label} canReview={canReview&&actionsEnabled} onReview={()=>setDialog('review')} onNavigate={navigate}/>:null}
        {contentReady&&view==='transactions'?<TransactionsView transactions={filteredTransactions} categoryMap={categoryMap} search={search} setSearch={setSearch} stateFilter={stateFilter} setStateFilter={setStateFilter} kindFilter={kindFilter} setKindFilter={setKindFilter} onExport={downloadCsv} canReview={canReview&&actionsEnabled} canImport={canEdit&&actionsEnabled} onImport={()=>setDialog('import')} onSelect={tx=>{setSelected(tx);setDialog('transaction');}}/>:null}
        {contentReady&&view==='budgets'?<BudgetsView budgets={budgets} categories={categories} spentByCategory={spentByCategory} totalBudget={totalBudget} budgetUse={budgetUse} canEdit={canEdit&&actionsEnabled} onAdd={()=>setDialog('budget')}/>:null}
        {contentReady&&view==='reports'?<ReportsView summary={summary} transactions={transactions} period={period} timezone={activeBook?.timezone??'Asia/Kolkata'} canVerify={canReview&&actionsEnabled} onExport={downloadCsv} onVerify={verifyPeriod}/>:null}
        {contentReady&&view==='people'?<PeopleView members={members} invitations={invitations} audit={audit} role={activeBook?.role??'viewer'} visibility={activeBook?.visibility??'private'} canManage={canManage&&actionsEnabled} actorUserId={actorUserId} saving={saving} onRole={updateRole} onRemove={removeMember} onRevoke={revokeInvitation} onInvite={()=>openEditor('invite')}/>:null}
        {contentReady&&view==='settings'?<SettingsView accounts={accounts} categories={categories} rules={rules} recurring={recurring} imports={imports} categoryMap={categoryMap} canManage={canManage&&actionsEnabled} canEdit={canEdit&&actionsEnabled} onAddAccount={()=>openEditor('account')} onAddCategory={()=>openEditor('category')} onAddRule={()=>openEditor('rule')} onAddRecurring={()=>openEditor('recurring')} onEdit={openEditor} onImport={()=>openEditor('import')}/>:null}
      </div></section>
    {dialog==='add'?<Modal title="Add a transaction" eyebrow="MANUAL ENTRY" onClose={()=>setDialog(null)}><p className="modal-copy">Use this for cash or whenever automatic capture is unavailable.</p><form onSubmit={addTransaction}><label>Merchant or source<input name="merchant" required autoFocus placeholder="e.g. Local grocery store"/></label><div className="form-row"><label>Type<select name="kind"><option value="expense">Expense</option><option value="income">Income</option><option value="refund">Refund</option></select></label><label>Amount in rupees<input name="amount" inputMode="decimal" pattern="[0-9,]+(\.[0-9]{1,2})?" required placeholder="0"/></label></div><div className="form-row"><label>Category<select name="categoryId">{categories.map(category=><option value={category.id} key={category.id}>{category.name}</option>)}</select></label><label>Date<input name="occurredAt" type="date" defaultValue={new Date().toLocaleDateString('en-CA',{timeZone:activeBook?.timezone??'Asia/Kolkata'})} required/></label></div><button className="primary-button submit" disabled={saving}>{saving?'Saving…':'Add transaction'}</button></form></Modal>:null}
    {dialog==='review'&&pending?<ReviewModal transaction={pending} categories={categories} saving={saving} onClose={()=>setDialog(null)} onSave={setCategory}/>:null}
    {dialog==='budget'?<Modal title="Set a monthly budget" eyebrow={`${period.label.toUpperCase()} PLAN`} onClose={()=>setDialog(null)}><p className="modal-copy">Choose a category and the most you want to spend.</p><form onSubmit={saveBudget}><label>Category<select name="categoryId">{categories.filter(category=>category.groupName!=='Income').map(category=><option value={category.id} key={category.id}>{category.name}</option>)}</select></label><div className="form-row"><label>Month<input name="month" type="month" defaultValue={period.value} required/></label><label>Budget in rupees<input name="amount" inputMode="numeric" required placeholder="6,000"/></label></div><button className="primary-button submit" disabled={saving}>{saving?'Saving…':'Save budget'}</button></form></Modal>:null}
    {dialog==='invite'?<Modal title="Invite someone to this book" eyebrow="PRIVATE ACCESS" onClose={()=>setDialog(null)}><p className="modal-copy">The invitation expires after seven days and works only for the matching signed-in email.</p><form onSubmit={inviteMember}><label>Email address<input name="email" type="email" required autoFocus placeholder="person@example.com"/></label><label>Role<select name="role"><option value="editor">Editor — add and categorize</option><option value="reviewer">CA reviewer — verify and reclassify</option><option value="viewer">Viewer — read and export</option></select></label><button className="primary-button submit" disabled={saving}>{saving?'Creating…':'Create and copy invite link'}</button></form></Modal>:null}
    {dialog==='profile'?<Modal title="Your profile" eyebrow="ACCOUNT" onClose={closeDialog}><p className="modal-copy">This is the name other members of a shared book see next to your changes.</p><form onSubmit={saveProfile}><label>Display name<input name="displayName" required autoFocus maxLength={120} defaultValue={userLabel}/></label><label>Email<input value={actorEmail} readOnly disabled/></label><p className="quiet">Your email and password are managed by your sign-in provider, not here. Use “Forgot your password?” on the sign-in screen to change your password.</p><button className="primary-button submit" disabled={saving}>{saving?'Saving…':'Save profile'}</button></form></Modal>:null}
    {dialog==='invite-link'&&inviteLink?<Modal title="Send this link" eyebrow="ONE-TIME INVITATION" onClose={closeDialog}><p className="modal-copy">Share it with {inviteLink.email} yourself — Paisa does not email invitations. The link is shown once and works only for that address.</p><InviteLink url={inviteLink.url}/><button className="primary-button submit" onClick={closeDialog}>Done</button></Modal>:null}
    {dialog==='transaction'&&selected?<TransactionModal transaction={selected} categoryMap={categoryMap} categories={categories} saving={saving} canReview={canReview&&actionsEnabled} canEdit={canEdit&&actionsEnabled} onClose={()=>{setDialog(null);setSelected(null);}} onSave={setCategory} onComment={postComment} onSplit={()=>setDialog('split')} onCorrect={correctTransaction} onVoid={voidTransaction}/>:null}
    {dialog==='split'&&selected?<SplitModal transaction={selected} categories={categories} saving={saving} onClose={()=>setDialog('transaction')} onSave={saveSplit}/>:null}
    {dialog==='account'?<Modal title={editing?'Edit account':'Add a financial account'} eyebrow="SOURCES" onClose={closeDialog}><p className="modal-copy">Accounts label where money moved. Paisa never connects to a bank or stores credentials.</p><form onSubmit={saveAccount}><label>Account name<input name="name" required autoFocus maxLength={80} defaultValue={(editing as AccountRecord|null)?.name??''} placeholder="e.g. Salary account"/></label><div className="form-row"><label>Type<select name="accountType" defaultValue={(editing as AccountRecord|null)?.accountType??'bank'}>{Object.entries(accountTypeLabels).map(([value,label])=><option value={value} key={value}>{label}</option>)}</select></label><label>Institution<input name="institution" maxLength={120} defaultValue={(editing as AccountRecord|null)?.institution??''} placeholder="Optional"/></label></div><label>Last digits<input name="accountMask" maxLength={8} inputMode="numeric" defaultValue={(editing as AccountRecord|null)?.accountMask??''} placeholder="Optional, e.g. 0042"/></label><button className="primary-button submit" disabled={saving}>{saving?'Saving…':editing?'Save account':'Add account'}</button>{editing?<RemoveButton label="Archive this account" note="Archiving hides it from new entries. Transactions that already reference it are unchanged." saving={saving} onRemove={removeSetting}/>:null}</form></Modal>:null}
    {dialog==='category'?<Modal title={editing?'Edit category':'Create a category'} eyebrow="CATEGORIES" onClose={closeDialog}><p className="modal-copy">Categories are shared across the books in this workspace.</p><form onSubmit={saveCategory}><label>Name<input name="name" required autoFocus maxLength={80} defaultValue={(editing as Category|null)?.name??''} placeholder="e.g. School fees"/></label><div className="form-row"><label>Group<select name="groupName" defaultValue={(editing as Category|null)?.groupName??'Essentials'}><option value="Essentials">Essentials</option><option value="Income">Income</option><option value="Lifestyle">Lifestyle</option><option value="Saving">Saving</option><option value="Other">Other</option></select></label><label>Colour<input name="color" type="color" defaultValue={(editing as Category|null)?.color??'#4f7d63'}/></label></div><button className="primary-button submit" disabled={saving}>{saving?'Saving…':editing?'Save category':'Create category'}</button>{editing?<RemoveButton label="Archive this category" note="Past transactions and budgets keep this category. It just stops appearing in new pickers." saving={saving} onRemove={removeSetting}/>:null}</form></Modal>:null}
    {dialog==='rule'?<Modal title={editing?'Edit rule':'Add a categorization rule'} eyebrow="AUTOMATIC SORTING" onClose={closeDialog}><p className="modal-copy">Rules apply to future captures only. Existing entries keep the category they were reviewed with.</p><form onSubmit={saveRule}><label>When a payment matches<select name="matchType" defaultValue={(editing as Rule|null)?.matchType??'merchant_exact'}>{Object.entries(matchTypeLabels).map(([value,label])=><option value={value} key={value}>{label}</option>)}</select></label><label>Merchant or UPI ID<input name="matchValue" required minLength={2} maxLength={160} defaultValue={(editing as Rule|null)?.matchValue??''} placeholder="e.g. Swiggy or landlord@okhdfcbank"/></label><div className="form-row"><label>Priority<input name="priority" type="number" min={1} max={1000} defaultValue={(editing as Rule|null)?.priority??100}/></label><label>Category<select name="categoryId" defaultValue={(editing as Rule|null)?.categoryId??categories[0]?.id}>{categories.map(category=><option value={category.id} key={category.id}>{category.name}</option>)}</select></label></div><button className="primary-button submit" disabled={saving}>{saving?'Saving…':editing?'Save rule':'Save rule'}</button>{editing?<RemoveButton label="Delete this rule" note="Future payments stop matching it. Nothing already categorized changes." saving={saving} onRemove={removeSetting}/>:null}</form></Modal>:null}
    {dialog==='recurring'?<Modal title={editing?'Edit recurring item':'Add a recurring item'} eyebrow="PLANNED MONEY" onClose={closeDialog}><p className="modal-copy">Recurring plans power the upcoming payments strip and take-home income planning.</p><form onSubmit={saveRecurring}><label>Name<input name="name" required autoFocus maxLength={120} defaultValue={(editing as Recurring|null)?.name??''} placeholder="e.g. Monthly rent"/></label><div className="form-row"><label>Type<select name="kind" defaultValue={(editing as Recurring|null)?.kind??'expense'}><option value="expense">Expense</option><option value="income">Income</option></select></label><label>Amount in rupees<input name="amount" inputMode="decimal" required defaultValue={editing?rupeesOf((editing as Recurring).amountMinor):''} placeholder="0"/></label></div><div className="form-row"><label>Repeats<select name="cadence" defaultValue={(editing as Recurring|null)?.cadence??'monthly'}><option value="monthly">Monthly</option><option value="weekly">Weekly</option><option value="quarterly">Quarterly</option><option value="yearly">Yearly</option></select></label><label>Next due<input name="nextDueAt" type="date" required defaultValue={(editing as Recurring|null)?.nextDueAt?.slice(0,10)??new Date().toISOString().slice(0,10)}/></label></div><label>Category<select name="categoryId" defaultValue={(editing as Recurring|null)?.categoryId??categories[0]?.id}>{categories.map(category=><option value={category.id} key={category.id}>{category.name}</option>)}</select></label><button className="primary-button submit" disabled={saving}>{saving?'Saving…':editing?'Save recurring item':'Save recurring item'}</button>{editing?<RemoveButton label="Stop this plan" note="The plan stops appearing in upcoming payments. Transactions it already produced stay in the ledger." saving={saving} onRemove={removeSetting}/>:null}</form></Modal>:null}
    {dialog==='import'?<ImportModal saving={saving} accounts={accounts} onClose={closeDialog} onImport={importStatement}/>:null}
    {toast?<div className="toast" role="status"><span>✓</span>{toast}</div>:null}
  </main>;
}

function Overview({summary,stats,transactions,categories,categoryMap,budgets,recurring,pending,spentByCategory,periodLabel,canReview,onReview,onNavigate}:{summary:Summary;stats:{label:string;value:string;detail:string;tone:string;icon:string}[];transactions:Transaction[];categories:Category[];categoryMap:Record<string,string>;budgets:Budget[];recurring:Recurring[];pending:Transaction|undefined;spentByCategory:(id:string)=>string;periodLabel:string;canReview:boolean;onReview:()=>void;onNavigate:(view:View)=>void}){
  // Built from whatever groups the book actually used, so the legend always adds
  // up to the Spent tile - two hardcoded groups hid uncategorized spending.
  const spendGroups=Object.values((summary.byCategory??[]).reduce<Record<string,{name:string;total:bigint;items:string[]}>>((groups,item)=>{const key=item.groupName||'Other';const group=groups[key]??={name:key,total:0n,items:[]};group.total+=BigInt(item.amountMinor);group.items.push(item.name);return groups;},{})).sort((a,b)=>b.total>a.total?1:b.total<a.total?-1:0);
  return <><section className="review-banner"><div className="review-icon">✓</div><div><strong>{summary.pendingReview?`${summary.pendingReview} payment${summary.pendingReview===1?'':'s'} need a quick review`:'You are all caught up'}</strong><p>{summary.pendingReview?'We captured them automatically. Confirm the categories while they are fresh.':'Every detected payment has been reviewed.'}</p></div>{canReview?<button onClick={onReview} disabled={!pending}>{pending?'Review now':'Reviewed'} <span>→</span></button>:null}</section><div className="stats-grid">{stats.map(stat=><article className={`stat-card ${stat.tone}`} key={stat.label}><div className="stat-head"><span>{stat.label}</span><i>{stat.icon}</i></div><strong>{stat.value}</strong><small>{stat.detail}</small></article>)}</div><div className="dashboard-grid"><article className="card spending-card"><div className="card-header"><div><p className="eyebrow">MONTHLY SPENDING</p><h2>Where your money went</h2></div><span className="period-button">{periodLabel}</span></div><div className="spending-body"><div className="donut" style={{'--ratio':`${Math.min(ratio(summary.spentMinor,summary.incomeMinor),100)}%`} as CSSProperties} aria-label={`${ratio(summary.spentMinor,summary.incomeMinor).toFixed(1)} percent of income spent`}><div><strong>{ratio(summary.spentMinor,summary.incomeMinor).toFixed(1)}%</strong><span>of income</span></div></div><div className="legend">{spendGroups.length?spendGroups.map((group,index)=><div key={group.name}><span className={`legend-dot g${index%5}`}/><p><b>{group.name}</b><small>{group.items.slice(0,3).join(', ')}</small></p><strong>{money(group.total.toString())}</strong></div>):<p className="quiet">No spending recorded this month yet.</p>}<button onClick={()=>onNavigate('reports')}>View category report <span>→</span></button></div></div></article><article className="card budget-card"><div className="card-header"><div><p className="eyebrow">BUDGET HEALTH</p><h2>{periodLabel} plan</h2></div><button className="text-button" onClick={()=>onNavigate('budgets')}>Manage</button></div>{budgets.slice(0,3).map(budget=>{const spent=spentByCategory(budget.categoryId);const used=ratio(spent,budget.amountMinor);return <div className={`budget-row ${used>=90?'warning':''}`} key={budget.id}><span>{categories.find(category=>category.id===budget.categoryId)?.name??'Category'}</span><b>{money(spent)} / {money(budget.amountMinor)}</b><i><em style={{width:`${Math.min(used,100)}%`}}/></i></div>;})}</article></div><article className="card transactions-card"><div className="card-header"><div><p className="eyebrow">RECENT ACTIVITY</p><h2>Latest transactions</h2></div><button className="text-button" onClick={()=>onNavigate('transactions')}>See all transactions <span>→</span></button></div><TransactionList transactions={transactions.slice(0,5)} categoryMap={categoryMap}/></article><section className="recurring-strip"><div><p className="eyebrow">COMING UP</p><h2>Recurring payments</h2></div>{recurring.slice(0,3).map(item=><article key={item.id}><span className={item.kind==='income'?'income':''}>{item.kind==='income'?'↓':'↗'}</span><div><strong>{item.name}</strong><small>{new Date(item.nextDueAt).toLocaleDateString('en-IN',{day:'numeric',month:'short'})} · {item.cadence}</small></div><b>{money(item.amountMinor,true)}</b></article>)}</section></>;
}

function TransactionsView({transactions,categoryMap,search,setSearch,stateFilter,setStateFilter,kindFilter,setKindFilter,onExport,onSelect,onImport,canReview,canImport}:{transactions:Transaction[];categoryMap:Record<string,string>;search:string;setSearch:(value:string)=>void;stateFilter:string;setStateFilter:(value:string)=>void;kindFilter:string;setKindFilter:(value:string)=>void;onExport:()=>void;onSelect:(tx:Transaction)=>void;onImport:()=>void;canReview:boolean;canImport:boolean}){return <section className="page-stack"><div className="page-heading"><div><p>Search, review, and reclassify the immutable ledger.</p></div><div className="heading-actions">{canImport?<button className="secondary-button" onClick={onImport}>⇧ Import statement</button>:null}<button className="secondary-button" onClick={onExport}>⇩ Export visible rows</button></div></div><div className="card transaction-workspace"><div className="filter-bar"><label className="table-search"><span>⌕</span><input aria-label="Filter transactions" placeholder="Merchant or category" value={search} onChange={event=>setSearch(event.target.value)}/></label><select aria-label="Filter by type" value={kindFilter} onChange={event=>setKindFilter(event.target.value)}><option value="all">All types</option><option value="expense">Expenses</option><option value="income">Income</option><option value="refund">Refunds</option></select><select aria-label="Filter by status" value={stateFilter} onChange={event=>setStateFilter(event.target.value)}><option value="all">All statuses</option><option value="pending_review">Needs review</option><option value="confirmed">Confirmed</option><option value="reconciled">Reconciled</option><option value="voided">Voided</option><option value="excluded">Excluded</option></select><span className="result-count">{transactions.length} loaded results</span></div>{transactions.length?<div className="ledger-table"><div className="ledger-head"><span>Transaction</span><span>Category</span><span>Status</span><span>Amount</span></div>{transactions.map((tx,index)=><button className="ledger-row" disabled={!canReview} onClick={()=>onSelect(tx)} key={tx.id}><span className={`transaction-mark ${['peach','blue','green','gold'][index%4]}`}>{(tx.merchant??'?')[0]}</span><span className="transaction-name"><strong>{tx.merchant??'Transaction'}</strong><small>{new Date(tx.occurredAt).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})} · {tx.sources?.[0]?.sourceType??'manual'}{tx.splits?.length?` · split ${tx.splits.length} ways`:''}{tx.comments?.length?` · ${tx.comments.length} comment${tx.comments.length===1?'':'s'}`:''}</small></span><span className="category-pill">{categoryMap[tx.categoryId??'']??'Uncategorized'}</span><StatusPill state={tx.state}/><strong className={tx.kind==='income'?'positive':''}>{money(tx.amountMinor,true)}</strong><span className="row-arrow">›</span></button>)}</div>:<div className="empty-state"><span>⌕</span><h2>No matching transactions</h2><p>Try clearing a filter or searching for a different merchant.</p></div>}</div><div className="ledger-note"><span>◇</span><p><strong>Source-safe ledger</strong><small>Imported amounts and original SMS or statement references cannot be overwritten. Every categorization and review action is audited.</small></p></div></section>;}

function BudgetsView({budgets,categories,spentByCategory,totalBudget,budgetUse,canEdit,onAdd}:{budgets:Budget[];categories:Category[];spentByCategory:(id:string)=>string;totalBudget:string;budgetUse:number;canEdit:boolean;onAdd:()=>void}){const spentTotal=budgets.reduce((sum,b)=>sum+BigInt(spentByCategory(b.categoryId)),0n);const remaining=BigInt(totalBudget)-spentTotal;return <section className="page-stack"><div className="page-heading"><div><p>Plan your month and catch overspending before it becomes a surprise.</p></div>{canEdit?<button className="primary-button" onClick={onAdd}>+ Set budget</button>:null}</div><div className="budget-summary"><article><p className="eyebrow">MONTHLY LIMIT</p><strong>{money(totalBudget)}</strong><small>Across {budgets.length} categories</small></article><article><p className="eyebrow">USED SO FAR</p><strong>{budgetUse.toFixed(0)}%</strong><small>{budgetUse>=90?'Close to your total limit':'Your plan is on track'}</small></article><article><p className="eyebrow">REMAINING</p><strong>{money((remaining>0n?remaining:0n).toString())}</strong><small>Available until month end</small></article></div><div className="budget-cards">{budgets.map(budget=>{const category=categories.find(item=>item.id===budget.categoryId);const spent=spentByCategory(budget.categoryId);const used=ratio(spent,budget.amountMinor);return <article className={`budget-detail-card ${used>=100?'over':used>=85?'near':''}`} key={budget.id}><div className="budget-card-top"><span style={{background:category?.color??'#789'}}>{category?.name?.[0]??'?'}</span><div><strong>{category?.name??'Category'}</strong><small>{category?.groupName??'Monthly budget'}</small></div><b>{used.toFixed(0)}%</b></div><div className="progress"><span style={{width:`${Math.min(used,100)}%`}}/></div><div className="budget-values"><strong>{money(spent)} spent</strong><span>{money(budget.amountMinor)} limit</span></div><p>{used>=100?`${money((BigInt(spent)-BigInt(budget.amountMinor)).toString())} over budget`: `${money((BigInt(budget.amountMinor)-BigInt(spent)).toString())} left`}</p></article>;})}</div></section>;}

function ReportsView({summary,transactions,period,timezone,canVerify,onExport,onVerify}:{summary:Summary;transactions:Transaction[];period:{value:string;label:string};timezone:string;canVerify:boolean;onExport:()=>void;onVerify:()=>void}){const savings=ratio(summary.savedMinor,summary.incomeMinor);const through=new Date(`${period.value}-01T00:00:00Z`);const months=Array.from({length:12},(_,index)=>{const date=new Date(Date.UTC(through.getUTCFullYear(),through.getUTCMonth()-11+index,1));const key=date.toISOString().slice(0,7);const amount=transactions.filter(tx=>tx.kind==='expense'&&!['excluded','voided'].includes(tx.state)&&monthKey(tx.occurredAt,timezone)===key).reduce((sum,tx)=>sum+-BigInt(tx.amountMinor),0n);return{key,label:date.toLocaleDateString('en-IN',{month:'short',timeZone:'UTC'}),amount};});const maximum=months.reduce((max,item)=>item.amount>max?item.amount:max,0n);return <section className="page-stack"><div className="page-heading"><div><p>Review monthly performance and prepare audit-ready exports.</p></div><div className="heading-actions"><button className="secondary-button" onClick={onExport}>⇩ Export visible rows</button>{canVerify?<button className="primary-button" onClick={onVerify}>✓ Verify {period.label}</button>:null}</div></div><div className="report-kpis"><article><span>↘</span><div><small>Savings rate</small><strong>{savings.toFixed(1)}%</strong><p>Available after current-period spending</p></div></article><article><span>◎</span><div><small>Needs review</small><strong>{summary.pendingReview}</strong><p>Resolve before verification</p></div></article><article><span>⇄</span><div><small>Loaded ledger entries</small><strong>{transactions.length}</strong><p>Across captured sources in this view</p></div></article></div><div className="report-grid"><article className="card trend-card"><div className="card-header"><div><p className="eyebrow">LOADED LEDGER TREND</p><h2>Spending momentum</h2></div><span className="trend-legend"><i/>Spending</span></div><div className="bar-chart" aria-label="Monthly spending trend from loaded ledger entries">{months.map(item=>{const height=maximum===0n?0:Number((item.amount*100n)/maximum);return <div key={item.key} aria-label={`${item.label}: ${money(item.amount.toString())}`}><span style={{height:`${Math.max(height,item.amount>0n?4:0)}%`}} title={money(item.amount.toString())}/><small>{item.label}</small></div>;})}</div></article><article className="card category-report"><div className="card-header"><div><p className="eyebrow">CATEGORY BREAKDOWN</p><h2>Top spending</h2></div></div>{(summary.byCategory??[]).slice(0,6).map((item,index)=><div key={item.categoryId??'uncategorized'}><span>{index+1}</span><p><strong>{item.name}</strong><small>{item.groupName}</small></p><b>{money(item.amountMinor)}</b></div>)}</article></div><div className="report-callout"><span>i</span><div><strong>Income reporting scope</strong><p>Paisa tracks salary credits and planned take-home income. CTC, tax estimates, filing, and financial advice are intentionally excluded from this release.</p></div></div></section>;}

function PeopleView({members,invitations,audit,role,visibility,canManage,actorUserId,saving,onRole,onRemove,onRevoke,onInvite}:{members:Member[];invitations:Invitation[];audit:AuditEvent[];role:string;visibility:string;canManage:boolean;actorUserId:string;saving:boolean;onRole:(member:Member,role:string)=>void;onRemove:(member:Member)=>void;onRevoke:(invitation:Invitation)=>void;onInvite:()=>void}){
  const owners=members.filter(member=>member.role==='book_owner').length;
  return <section className="page-stack"><div className="page-heading"><div><p>Control who can see this {visibility} book and what they are allowed to change.</p></div><div className="heading-actions"><span className="role-chip">Your role: {roleLabels[role]??role.replace('_',' ')}</span>{canManage?<button className="primary-button" onClick={onInvite}>+ Invite person</button>:null}</div></div><div className="people-grid"><article className="card member-card"><div className="card-header"><div><p className="eyebrow">BOOK MEMBERS</p><h2>{members.length} {members.length===1?'person has':'people have'} access</h2></div><span className="privacy-badge">{visibility==='private'?'▣ Private':'◎ Shared'}</span></div><div className="member-list">{members.map(member=>{
    const isSelf=member.userId===actorUserId; const lastOwner=member.role==='book_owner'&&owners<2; const locked=isSelf||lastOwner;
    return <div className="member" key={member.userId}><span className="avatar">{initials(member.user.displayName,member.user.email)}</span><p><strong>{member.user.displayName??member.user.email}{isSelf?<em className="self-tag">you</em>:null}</strong><small>{member.user.email}</small></p>
      {canManage&&!locked?<select aria-label={`Role for ${member.user.displayName??member.user.email}`} value={member.role} onChange={event=>void onRole(member,event.target.value)}>{Object.entries(roleLabels).map(([value,label])=><option value={value} key={value}>{label}</option>)}</select>:<span className="role-chip">{roleLabels[member.role]??member.role.replace('_',' ')}</span>}
      {canManage&&!locked?<RemoveButton label="Remove access" note={`${member.user.displayName??member.user.email} loses access to this book immediately. Nothing they recorded is deleted.`} saving={saving} onRemove={()=>onRemove(member)} compact/>:<i className="member-status">{isSelf?'Signed in':lastOwner?'Only owner':'Active'}</i>}</div>;})}</div>
    {canManage?<p className="quiet settings-hint">{owners<2?'Your own access is locked because you are this book’s only owner. Promote someone to Book owner to be able to change it.':'You cannot change your own access. Another owner can do it for you.'}</p>:null}
    {invitations.length?<div className="pending-invites"><p className="eyebrow">PENDING INVITATIONS</p>{invitations.map(invitation=><div key={invitation.id}><span className="avatar">{initials(null,invitation.email)}</span><p><strong>{invitation.email}</strong><small>{roleLabels[invitation.role]??invitation.role} · expires {new Date(invitation.expiresAt).toLocaleDateString('en-IN',{day:'numeric',month:'short'})}</small></p>{canManage?<RemoveButton label="Revoke" note={`The invitation link sent to ${invitation.email} stops working.`} saving={saving} onRemove={()=>onRevoke(invitation)} compact/>:<i>Pending</i>}</div>)}</div>:null}
    <div className="invite-note"><span>＋</span><p><strong>Invite-only access</strong><small>Invite links expire after seven days, are bound to one email address, and grant access only to this book.</small></p></div></article><article className="card audit-card"><div className="card-header"><div><p className="eyebrow">RECENT AUDIT TRAIL</p><h2>Every change is attributable</h2></div></div><div className="audit-list">{audit.length?audit.slice(0,6).map(event=><div key={event.id}><span/><p><strong>{readableAction(event.action)}</strong><small>{event.actorId.replace('user_','')} · {new Date(event.createdAt).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'})}</small></p></div>):<p className="quiet">No changes recorded in this book yet.</p>}</div></article></div><article className="card access-matrix"><div className="card-header"><div><p className="eyebrow">PERMISSION MODEL</p><h2>Clear boundaries by role</h2></div></div><div className="matrix"><div className="matrix-head"><span>Capability</span><b>Owner</b><b>Editor</b><b>CA reviewer</b><b>Viewer</b></div>{[['View and export','✓','✓','✓','✓'],['Categorize and comment','✓','✓','✓','—'],['Split and verify periods','✓','✓','✓','—'],['Add transactions and budgets','✓','✓','—','—'],['Manage people and sources','✓','—','—','—'],['Change imported amounts','—','—','—','—']].map(row=><div className="matrix-row" key={row[0]}>{row.map((cell,index)=>index===0?<span key={cell}>{cell}</span>:<b className={cell==='✓'?'allowed':''} key={index}>{cell}</b>)}</div>)}</div></article></section>;}

function SettingsView({accounts,categories,rules,recurring,imports,categoryMap,canManage,canEdit,onAddAccount,onAddCategory,onAddRule,onAddRecurring,onEdit,onImport}:{accounts:AccountRecord[];categories:Category[];rules:Rule[];recurring:Recurring[];imports:ImportRecord[];categoryMap:Record<string,string>;canManage:boolean;canEdit:boolean;onAddAccount:()=>void;onAddCategory:()=>void;onAddRule:()=>void;onAddRecurring:()=>void;onEdit:(dialog:Dialog,record:AccountRecord|Category|Rule|Recurring)=>void;onImport:()=>void}){
  const grouped=categories.reduce<Record<string,Category[]>>((groups,category)=>({...groups,[category.groupName??'Other']:[...(groups[category.groupName??'Other']??[]),category]}),{});
  return <section className="page-stack"><div className="page-heading"><div><p>Configure the sources, categories, and rules this book uses to sort money automatically.</p></div>{canEdit?<button className="secondary-button" onClick={onImport}>⇧ Import statement</button>:null}</div>
    <div className="settings-grid">
      <article className="card"><div className="card-header"><div><p className="eyebrow">ACCOUNTS</p><h2>Where money moves</h2></div>{canManage?<button className="text-button" onClick={onAddAccount}>+ Add account</button>:null}</div><div className="settings-list">{accounts.length?accounts.map(account=><SettingsRow key={account.id} editable={canManage} onEdit={()=>onEdit('account',account)} label={`Edit ${account.name}`} mark={(account.name||'?')[0]} title={account.name} detail={[accountTypeLabels[account.accountType]??account.accountType,account.institution,account.accountMask?`•••• ${account.accountMask}`:null].filter(Boolean).join(' · ')}/>):<p className="quiet">No accounts yet. Add one to label where each payment came from.</p>}</div><div className="invite-note"><span>◇</span><p><strong>No bank connection</strong><small>Accounts are labels only. Paisa never stores banking passwords, UPI PINs, or card numbers.</small></p></div></article>
      <article className="card"><div className="card-header"><div><p className="eyebrow">CATEGORIZATION RULES</p><h2>{rules.length} automatic rule{rules.length===1?'':'s'}</h2></div>{canEdit?<button className="text-button" onClick={onAddRule}>+ Add rule</button>:null}</div><div className="settings-list">{rules.length?rules.map(rule=><SettingsRow key={rule.id} editable={canEdit} onEdit={()=>onEdit('rule',rule)} label={`Edit rule for ${rule.matchValue}`} mark={String(rule.priority)} markTone="rule" title={`${matchTypeLabels[rule.matchType]??rule.matchType} “${rule.matchValue}”`} detail={`Files future payments under ${categoryMap[rule.categoryId]??'a category'}`}/>):<p className="quiet">No rules yet. Confirming a payment with “apply to future” creates one automatically.</p>}</div><div className="invite-note"><span>↻</span><p><strong>Future payments only</strong><small>Rules never rewrite entries you already reviewed, and an explicit choice on a transaction always wins.</small></p></div></article>
      <article className="card"><div className="card-header"><div><p className="eyebrow">RECURRING PLANS</p><h2>Planned money</h2></div>{canEdit?<button className="text-button" onClick={onAddRecurring}>+ Add recurring</button>:null}</div><div className="settings-list">{recurring.length?recurring.map(plan=><SettingsRow key={plan.id} editable={canEdit} onEdit={()=>onEdit('recurring',plan)} label={`Edit ${plan.name}`} mark={plan.kind==='income'?'↓':'↗'} markTone={plan.kind==='income'?'income':''} title={plan.name} detail={`${plan.cadence} · next ${new Date(plan.nextDueAt).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}`} trailing={<b>{money(plan.amountMinor,true)}</b>}/>):<p className="quiet">No recurring plans yet.</p>}</div></article>
      <article className="card"><div className="card-header"><div><p className="eyebrow">STATEMENT IMPORTS</p><h2>Reconciliation queue</h2></div>{canEdit?<button className="text-button" onClick={onImport}>+ Import file</button>:null}</div><div className="settings-list">{imports.length?imports.map(record=><SettingsRow key={record.id} mark={record.contentType==='application/pdf'?'PDF':'CSV'} title={`${fileSize(record.sizeBytes)} statement`} detail={`${new Date(record.createdAt).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})} · fingerprint ${record.sha256.slice(0,10)}`} trailing={<i className="member-status">{(record.status??'upload_pending').replaceAll('_',' ')}</i>}/>):<p className="quiet">No statements imported into this book yet.</p>}</div><div className="invite-note"><span>◈</span><p><strong>Duplicate-safe</strong><small>Re-importing the same file is detected by its fingerprint, so the ledger never gains a second copy.</small></p></div></article>
      <article className="card categories-card"><div className="card-header"><div><p className="eyebrow">CATEGORIES</p><h2>{categories.length} in this workspace</h2></div>{canEdit?<button className="text-button" onClick={onAddCategory}>+ Add category</button>:null}</div><div className="category-groups">{Object.entries(grouped).map(([group,items])=><div key={group}><p className="eyebrow">{group.toUpperCase()}</p><div>{items.map(category=>canEdit?<button className="category-chip editable" key={category.id} onClick={()=>onEdit('category',category)} aria-label={`Edit ${category.name}`}><i style={{background:category.color??'#8ba989'}}/>{category.name}<em>✎</em></button>:<span className="category-chip" key={category.id}><i style={{background:category.color??'#8ba989'}}/>{category.name}</span>)}</div></div>)}</div>{canEdit?<p className="quiet settings-hint">Select any category, account, rule, or plan to edit or remove it.</p>:null}</article>
    </div></section>;}

function SettingsRow({mark,markTone='',title,detail,trailing,editable=false,onEdit,label}:{mark:string;markTone?:string;title:string;detail:string;trailing?:React.ReactNode;editable?:boolean;onEdit?:()=>void;label?:string}){
  const content=<><span className={`settings-mark ${markTone}`}>{mark}</span><p><strong>{title}</strong><small>{detail}</small></p>{trailing??null}{editable?<em className="row-edit" aria-hidden="true">✎</em>:null}</>;
  return editable?<button type="button" className="settings-item editable" onClick={onEdit} aria-label={label}>{content}</button>:<div className="settings-item">{content}</div>;}

function InviteLink({url}:{url:string}){
  const [copied,setCopied]=useState('');
  const field=useRef<HTMLInputElement>(null);
  async function copy(){try{await navigator.clipboard.writeText(url);setCopied('Link copied');}catch{field.current?.select();setCopied('Press ⌘C or Ctrl+C to copy the selected link');}}
  return <div className="invite-link"><input ref={field} readOnly value={url} aria-label="Invitation link" onFocus={event=>event.currentTarget.select()}/><button type="button" className="secondary-button" onClick={()=>void copy()}>Copy</button>{copied?<small role="status">{copied}</small>:null}</div>;}

function RemoveButton({label,note,saving,onRemove,compact=false}:{label:string;note:string;saving:boolean;onRemove:()=>void;compact?:boolean}){
  const [armed,setArmed]=useState(false);
  return <div className={compact?'remove-row compact':'remove-row'}>{armed?<><p>{note}</p><div><button type="button" className="danger-button" disabled={saving} onClick={onRemove}>{saving?'Working…':`Yes, ${label.toLowerCase()}`}</button><button type="button" className="text-button" disabled={saving} onClick={()=>setArmed(false)}>Cancel</button></div></>:<button type="button" className="text-button danger-link" onClick={()=>setArmed(true)}>{label}</button>}</div>;}

function TransactionList({transactions,categoryMap}:{transactions:Transaction[];categoryMap:Record<string,string>}){return <div className="transaction-list">{transactions.map((tx,index)=><div className="transaction" key={tx.id}><span className={`transaction-mark ${['peach','blue','green','gold'][index%4]}`}>{(tx.merchant??'?')[0]}</span><div className="transaction-name"><strong>{tx.merchant??'Transaction'}</strong><small>{tx.meta??new Date(tx.occurredAt).toLocaleDateString('en-IN',{day:'numeric',month:'short'})} · {tx.state.replaceAll('_',' ')}</small></div><span className="category-pill">{categoryMap[tx.categoryId??'']??'Uncategorized'}</span><strong className={tx.kind==='income'?'positive':''}>{money(tx.amountMinor,true)}</strong></div>)}</div>;}
function StatusPill({state}:{state:string}){return <span className={`status-pill ${state}`}>{state==='pending_review'?'Needs review':state.replaceAll('_',' ')}</span>;}
function Modal({title,eyebrow,onClose,children}:{title:string;eyebrow:string;onClose:()=>void;children:React.ReactNode}){const ref=useRef<HTMLElement>(null);useEffect(()=>{const previous=document.activeElement as HTMLElement|null;const element=ref.current;if(!element)return;const focusable=()=>Array.from(element.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[href],[tabindex]:not([tabindex="-1"])'));(element.querySelector<HTMLElement>('[autofocus]')??focusable()[0]??element).focus();const trap=(event:KeyboardEvent)=>{if(event.key!=='Tab')return;const items=focusable();if(!items.length){event.preventDefault();return;}const first=items[0],last=items.at(-1)!;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}};element.addEventListener('keydown',trap);return()=>{element.removeEventListener('keydown',trap);previous?.focus();};},[]);return <div className="modal-backdrop" role="presentation" onMouseDown={onClose}><section ref={ref} className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabIndex={-1} onMouseDown={event=>event.stopPropagation()}><button className="modal-close" onClick={onClose} aria-label="Close">×</button><p className="eyebrow">{eyebrow}</p><h2 id="modal-title">{title}</h2>{children}</section></div>;}
function ReviewModal({transaction,categories,saving,onClose,onSave}:{transaction:Transaction;categories:Category[];saving:boolean;onClose:()=>void;onSave:(tx:Transaction,categoryId:string,future?:boolean)=>void}){function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);void onSave(transaction,String(form.get('categoryId')),form.get('future')==='on');}return <Modal title="Does this category look right?" eyebrow="AUTOMATIC CAPTURE" onClose={onClose}><div className="review-transaction"><span>{(transaction.merchant??'?')[0]}</span><div><strong>{transaction.merchant}</strong><small>{new Date(transaction.occurredAt).toLocaleString('en-IN')}</small></div><b>{money(transaction.amountMinor,true)}</b></div><form onSubmit={submit}><label>Category<select name="categoryId" defaultValue={transaction.categoryId??'cat_other'}>{categories.map(category=><option value={category.id} key={category.id}>{category.name}</option>)}</select></label><label className="checkbox"><input type="checkbox" name="future"/> Use this category for the same merchant in future</label><button className="primary-button submit" disabled={saving}>{saving?'Confirming…':'Confirm payment'}</button></form></Modal>;}
function TransactionModal({transaction,categoryMap,categories,saving,canReview,canEdit,onClose,onSave,onComment,onSplit,onCorrect,onVoid}:{transaction:Transaction;categoryMap:Record<string,string>;categories:Category[];saving:boolean;canReview:boolean;canEdit:boolean;onClose:()=>void;onSave:(tx:Transaction,categoryId:string,future?:boolean)=>void;onComment:(tx:Transaction,body:string)=>void;onSplit:()=>void;onCorrect:(tx:Transaction,fields:Record<string,string>)=>void;onVoid:(tx:Transaction)=>void}){
  const [comment,setComment]=useState('');const [correcting,setCorrecting]=useState(false);
  // Only a manual entry can be corrected: an imported amount is the bank's word.
  const manual=(transaction.sources??[]).every(source=>source.sourceType==='manual');
  const voided=transaction.state==='voided';
  const debit=BigInt(transaction.amountMinor)<0n;
  function submitCorrection(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);const kind=String(form.get('kind'));
    // An imported row keeps the bank's amount and date; only what it was for can change.
    if(!manual){void onCorrect(transaction,{kind,amountMinor:transaction.amountMinor});return;}
    const minor=rupeesToMinor(String(form.get('amount')));
    // Expenses are negative, income and refunds positive; a transfer keeps the direction it already had.
    const negative=kind==='expense'||(kind==='transfer'&&debit);
    void onCorrect(transaction,{kind,amountMinor:negative?`-${minor}`:minor,merchant:String(form.get('merchant')).trim(),occurredAt:new Date(`${String(form.get('occurredAt'))}T00:00:00.000+05:30`).toISOString()});}
  function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);void onSave(transaction,String(form.get('categoryId')),form.get('future')==='on');}
  function submitComment(event:FormEvent<HTMLFormElement>){event.preventDefault();const body=comment.trim();if(!body)return;setComment('');void onComment(transaction,body);}
  return <Modal title={transaction.merchant??'Transaction details'} eyebrow="LEDGER ENTRY" onClose={onClose}><div className="transaction-detail"><div><small>Amount</small><strong className={transaction.kind==='income'?'positive':''}>{money(transaction.amountMinor,true)}</strong></div><div><small>Date</small><strong>{new Date(transaction.occurredAt).toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'})}</strong></div><div><small>Status</small><StatusPill state={transaction.state}/></div><div><small>Source</small><strong>{transaction.sources?.[0]?.sourceType??'manual'}</strong></div></div><div className="immutable-note"><span>◇</span><p><strong>{manual?'Manual entry':'Original amount protected'}</strong><small>{manual?'You typed this one, so it can be corrected. Every change is audited.':'The amount and date stay as the bank sent them. You can still change what it was for — a payment to your own account is a transfer, not spending.'}</small></p></div>
    {voided?<div className="immutable-note"><span>⊘</span><p><strong>Voided</strong><small>This entry stays in the ledger for the audit trail but no longer counts towards any month.</small></p></div>:null}
    {transaction.splits?.length?<div className="split-summary"><p className="eyebrow">SPLIT ACROSS CATEGORIES</p>{transaction.splits.map(split=><div key={split.id}><span>{categoryMap[split.categoryId]??'Uncategorized'}</span><b>{money(split.amountMinor)}</b></div>)}</div>:null}
    <form onSubmit={submit}><label>Category<select name="categoryId" defaultValue={transaction.categoryId??'cat_other'}>{categories.map(category=><option value={category.id} key={category.id}>{category.name}</option>)}</select></label><label className="checkbox"><input type="checkbox" name="future"/> Apply to future payments from this merchant</label><div className="modal-actions"><button className="primary-button submit" disabled={saving}>{saving?'Saving…':categoryMap[transaction.categoryId??'']?'Save changes':'Confirm transaction'}</button>{canReview?<button type="button" className="secondary-button" onClick={onSplit}>{transaction.splits?.length?'Edit split':'Split transaction'}</button>:null}{canEdit&&!voided?<button type="button" className="secondary-button" onClick={()=>setCorrecting(value=>!value)}>{correcting?'Cancel':manual?'Correct amount':'Change type'}</button>:null}</div></form>
    {correcting&&canEdit&&!voided?<form onSubmit={submitCorrection} className="correction-form"><p className="eyebrow">{manual?'CORRECT THIS ENTRY':'WHAT WAS THIS FOR?'}</p>
      {manual?<label>Merchant<input name="merchant" defaultValue={transaction.merchant??''} maxLength={160} required/></label>:null}
      <label>Type<select name="kind" defaultValue={transaction.kind}>{(manual?[['expense','Expense'],['income','Income'],['refund','Refund'],['transfer','Transfer between my accounts']]:debit?[['expense','Expense'],['transfer','Transfer to my own account'],['refund','Refund I paid out']]:[['income','Income'],['transfer','Transfer from my own account'],['refund','Refund I received']]).map(([value,label])=><option value={value} key={value}>{label}</option>)}</select></label>
      {manual?<><label>Amount (₹)<input name="amount" defaultValue={rupeesOf(transaction.amountMinor)} inputMode="decimal" required/></label>
      <label>Date<input name="occurredAt" type="date" defaultValue={new Date(transaction.occurredAt).toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'})} required/></label></>:<p className="quiet">A transfer keeps its record but stops counting as money spent.</p>}
      <button className="primary-button submit" disabled={saving}>{saving?'Saving…':manual?'Save correction':'Save type'}</button></form>:null}
    {canEdit&&!voided?<RemoveButton label="Void this entry" note="Voiding keeps the entry and its history but removes it from every total. This cannot be undone from here." saving={saving} onRemove={()=>onVoid(transaction)}/>:null}
    {canReview?<section className="comment-thread"><p className="eyebrow">REVIEW NOTES</p>{transaction.comments?.length?transaction.comments.map(entry=><article key={entry.id}><span className="avatar small">{initials(null,entry.authorId.replace('user_',''))}</span><p><strong>{entry.body}</strong><small>{entry.authorId.replace('user_','')} · {new Date(entry.createdAt).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'})}</small></p></article>):<p className="quiet">No review notes yet. Comments are audited and visible to everyone with access to this book.</p>}<form onSubmit={submitComment}><label>Add a note<textarea value={comment} onChange={event=>setComment(event.target.value)} maxLength={2000} rows={2} placeholder="Ask a question or explain this entry"/></label><button className="secondary-button" disabled={saving||!comment.trim()}>{saving?'Saving…':'Post note'}</button></form></section>:null}
  </Modal>;}
function SplitModal({transaction,categories,saving,onClose,onSave}:{transaction:Transaction;categories:Category[];saving:boolean;onClose:()=>void;onSave:(tx:Transaction,parts:{categoryId:string;amount:string}[])=>void}){
  const total=money(transaction.amountMinor);
  const [parts,setParts]=useState<{categoryId:string;amount:string}[]>(()=>transaction.splits?.length?transaction.splits.map(split=>({categoryId:split.categoryId,amount:rupeesOf(split.amountMinor)})):[{categoryId:transaction.categoryId??categories[0]?.id??'',amount:rupeesOf(transaction.amountMinor)},{categoryId:categories[0]?.id??'',amount:'0'}]);
  function update(index:number,change:Partial<{categoryId:string;amount:string}>){setParts(items=>items.map((item,position)=>position===index?{...item,...change}:item));}
  return <Modal title="Split this transaction" eyebrow={`TOTAL ${total}`} onClose={onClose}><p className="modal-copy">Divide the captured amount across categories. The imported total never changes and every split is audited.</p>
    <form onSubmit={event=>{event.preventDefault();void onSave(transaction,parts);}}><div className="split-editor">{parts.map((part,index)=><div key={index}><select aria-label={`Category for part ${index+1}`} value={part.categoryId} onChange={event=>update(index,{categoryId:event.target.value})}>{categories.map(category=><option value={category.id} key={category.id}>{category.name}</option>)}</select><input aria-label={`Amount for part ${index+1}`} inputMode="decimal" value={part.amount} onChange={event=>update(index,{amount:event.target.value})} placeholder="0"/>{parts.length>2?<button type="button" aria-label={`Remove part ${index+1}`} onClick={()=>setParts(items=>items.filter((_,position)=>position!==index))}>×</button>:<span/>}</div>)}</div>
    {parts.length<20?<button type="button" className="text-button add-split" onClick={()=>setParts(items=>[...items,{categoryId:categories[0]?.id??'',amount:'0'}])}>+ Add another part</button>:null}
    <button className="primary-button submit" disabled={saving}>{saving?'Saving…':`Save split of ${total}`}</button></form></Modal>;}
function ImportModal({saving,accounts,onClose,onImport}:{saving:boolean;accounts:AccountRecord[];onClose:()=>void;onImport:(file:File,accountId:string)=>void}){
  const [file,setFile]=useState<File|null>(null); const [accountId,setAccountId]=useState('');
  const isCsv=Boolean(file&&(file.type==='text/csv'||file.name.toLowerCase().endsWith('.csv')));
  return <Modal title="Import a bank statement" eyebrow="CSV OR PDF" onClose={onClose}><p className="modal-copy">CSV statements are read on upload and each row is added for review. Entries already captured from SMS are reconciled instead of duplicated.</p>
    <form onSubmit={event=>{event.preventDefault();if(file)void onImport(file,accountId);}}><label className="file-field">Statement file<input type="file" accept=".csv,.pdf,text/csv,application/pdf" onChange={event=>setFile(event.target.files?.[0]??null)} required/></label>
    {accounts.length?<label>Bank account<select value={accountId} onChange={event=>setAccountId(event.target.value)}><option value="">Not linked to an account</option>{accounts.map(account=><option key={account.id} value={account.id}>{account.name}</option>)}</select></label>:null}
    {file?<div className="file-preview"><span>▤</span><p><strong>{file.name}</strong><small>{fileSize(file.size)} · fingerprinted in this browser before upload</small></p></div>:null}
    <button className="primary-button submit" disabled={saving||!file}>{saving?'Importing…':isCsv?'Import entries':'Queue import'}</button></form></Modal>;}
function signInMessage(error:unknown){const code=typeof error==='object'&&error&&'code' in error?String((error as {code:unknown}).code):'';return ({'auth/invalid-credential':'That email and password combination is not recognised.','auth/wrong-password':'That email and password combination is not recognised.','auth/user-not-found':'That email and password combination is not recognised.','auth/invalid-email':'Enter a valid email address.','auth/user-disabled':'This account has been disabled. Ask the workspace owner to restore it.','auth/too-many-requests':'Too many attempts. Wait a few minutes before trying again.','auth/network-request-failed':'Cannot reach the authentication service. Check your connection.','auth/multi-factor-auth-required':'This account requires a second factor, which this build cannot complete yet.','auth/operation-not-allowed':'Email sign-in is not enabled for this Firebase project.'} as Record<string,string>)[code]??(code.startsWith('auth/api-key-not-valid')||code==='auth/invalid-api-key'?'Authentication is not configured for this deployment.':'Sign-in failed. Verify your email and check your credentials.');}
function SignIn(){const[message,setMessage]=useState('');const[busy,setBusy]=useState(false);const[hasInvite]=useState(()=>Boolean(invitationToken()));async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);setMessage('');const form=new FormData(event.currentTarget);try{await signIn(String(form.get('email')),String(form.get('password')));}catch(error){setMessage(signInMessage(error));}finally{setBusy(false);}}async function createAccount(event:React.MouseEvent<HTMLButtonElement>){const form=event.currentTarget.form;if(!form||!form.reportValidity())return;setBusy(true);setMessage('');const data=new FormData(form);try{await registerInvitedUser(String(data.get('email')),String(data.get('password')));setMessage('Account created. Verify your email, then return here and sign in.');}catch{setMessage('Could not create the account. It may already exist; try signing in.');}finally{setBusy(false);}}async function resetPassword(event:React.MouseEvent<HTMLButtonElement>){const email=event.currentTarget.form?.querySelector<HTMLInputElement>('input[name=email]');if(!email?.value||!email.checkValidity()){setMessage('Enter your email address first, then choose reset.');return;}setBusy(true);setMessage('');try{await sendPasswordReset(email.value);setMessage(`If ${email.value} has an account, a reset link is on its way.`);}catch(error){setMessage(signInMessage(error));}finally{setBusy(false);}}return <main className="auth-page"><section className="auth-card"><div className="brand auth-brand"><span className="brand-mark">₹</span><span>Paisa</span></div><p className="eyebrow">PRIVATE FINANCIAL WORKSPACE</p><h1>Your finances, clearly shared.</h1><p>{hasInvite?'Create or sign in to the exact email address that received this invitation.':'Sign in to your private book, household workspace, or CA review view.'}</p><form onSubmit={submit}><label>Email<input name="email" type="email" autoComplete="email" required/></label><label>Password<input name="password" type="password" autoComplete={hasInvite?'new-password':'current-password'} minLength={8} required/></label>{message?<p className="form-error" role="status">{message}</p>:null}<button className="primary-button" disabled={busy}>{busy?'Please wait…':'Sign in securely'}</button>{hasInvite?<button type="button" className="secondary-button" disabled={busy} onClick={createAccount}>Create invited account</button>:null}<button type="button" className="text-button reset-link" disabled={busy} onClick={resetPassword}>Forgot your password?</button></form><small>Access is available only to users invited by a workspace owner.</small></section></main>;}
